/**
 * The stop watch on one launched cloud agent: a one-shot reminder at its
 * deadline. The agent's status webhook (`channels/cursor-cloud-agents.ts`)
 * fires it early, when the agent's run stops. Every fire is host-only, so no
 * model turn starts until the one wake.
 *
 * - An early fire on a stopped agent wakes the bound conversation once, with
 *   how the latest run ended, and ends the watch. The stop the signed webhook
 *   saved (`lib/stop-signal.ts`) counts without a status read.
 * - An early fire on an agent that still runs (a replayed or early webhook)
 *   keeps the watch until the deadline.
 * - A wake that was not sent, or a status read that failed, tries again in a
 *   minute, at most 10 times.
 * - The deadline fire stops with no read and no wake.
 *
 * A fire never throws, because a v1 host stops firing a reminder whose
 * handler threw; every outcome is a skip or a stop.
 */
import * as z from "zod/v4";
import { CursorBackendError } from "../../../internal/cursor/backend-client.js";
import { describeError } from "../../../internal/describe-error.js";
import { ReminderFollowupNotSentError } from "../../../internal/reminder-followup-error.js";
import { defineReminder } from "../../../reminders.js";
import { cloudAgentsBackend, isStopped, isStoppedRun, } from "../lib/backend.js";
import { readStopSignal } from "../lib/stop-signal.js";
/** How long a watch waits for the agent's webhook before it stops without a wake. */
export const WATCH_WINDOW_HOURS = 24;
const RETRY_DELAY = "1m";
const MAX_RETRIES = 10;
const watchArgs = z.object({
    agentId: z.string().min(1),
    deadline: z.string().datetime(),
    previousRunId: z.string().min(1).optional(),
});
const watch = defineReminder({
    async run(fire) {
        const parsed = watchArgs.safeParse(fire.args);
        if (!parsed.success) {
            return { action: "stop" };
        }
        const { agentId, deadline, previousRunId } = parsed.data;
        if (Date.now() >= Date.parse(deadline)) {
            return { action: "stop" };
        }
        const retry = (reason) => {
            if (fire.fireCount >= MAX_RETRIES) {
                console.warn(`[cursor-cloud-agents] gave up waking for ${agentId}: ${reason}`);
                return { action: "stop" };
            }
            console.warn(`[cursor-cloud-agents] could not wake for ${agentId} yet (${reason}); trying again in ${RETRY_DELAY}`);
            return { action: "skip", reschedule: { delay: RETRY_DELAY } };
        };
        // A stop the signed webhook reported after this watch was armed needs no
        // status read, which can lag the write behind it.
        const armedAt = Date.parse(deadline) - WATCH_WINDOW_HOURS * 3_600_000;
        const signal = await readStopSignal(fire.host.kv, agentId, armedAt);
        let status;
        if (signal !== undefined) {
            status = signal.status;
        }
        else {
            try {
                status = (await cloudAgentsBackend().info(agentId)).status;
            }
            catch (error) {
                if (isPermanent(error)) {
                    console.warn(`[cursor-cloud-agents] stopped watching ${agentId}: ${describeError(error)}`);
                    return { action: "stop" };
                }
                return retry(describeError(error));
            }
        }
        if (!isStopped(status)) {
            return { action: "skip", reschedule: { at: deadline } };
        }
        const run = await latestRunOf(agentId);
        // A follow-up's watch: the run before it, or a run that has not stopped, is
        // not this watch's stop. A saved webhook stop names no run.
        if (previousRunId !== undefined &&
            (run?.id === previousRunId || (run?.status !== undefined && !isStoppedRun(run.status)))) {
            // A late webhook for the stop before the follow-up.
            return { action: "skip", reschedule: { at: deadline } };
        }
        // A cancelled run leaves the agent `finished`; only the run says it was cancelled.
        const stoppedAs = run?.status === "CANCELLED" ? "cancelled" : status;
        // At most once: a wake that failed may already have started its turn.
        // Try again only when the wake was not sent and the conversation exists.
        try {
            await fire.followup({
                message: `[cloud agent stopped] ${agentId} is ${stoppedAs}. Call cloud__get to read its result.`,
            });
        }
        catch (error) {
            if (error instanceof ReminderFollowupNotSentError && error.reason !== "session_gone") {
                return retry(error.reason);
            }
            console.warn(`[cursor-cloud-agents] could not wake the conversation watching ${agentId}: ${describeError(error)}`);
        }
        return { action: "stop" };
    },
});
export default watch;
/** The agent's latest run. A failed read gives undefined, so the wake still goes out. */
async function latestRunOf(agentId) {
    try {
        return await cloudAgentsBackend().latestRun(agentId);
    }
    catch (error) {
        console.warn(`[cursor-cloud-agents] could not read the latest run of ${agentId}: ${describeError(error)}`);
        return undefined;
    }
}
/** The agent is gone or out of the host key's reach; trying again will not bring it back. */
function isPermanent(error) {
    return error instanceof CursorBackendError && (error.status === 403 || error.status === 404);
}
